def _draw_bullet(self, b):
    path = ("mine" if b.kind == "mine" else "homing_missile" if b.kind == "missile"
            else "cannon_shell" if b.kind == "shell" else "enemy_plasma" if b.team == "enemy" else "player_plasma")
