def _spawn_scale(self, oid, frame):
    t = (frame - self._first_seen.get(oid, -999)) / SPAWN_FRAMES
    if t >= 1:
        return 1.0
    t = max(0.0, t)
    return 1 - (1 - t) ** 3  # ease-out

